 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    horizontal = [[0] * w for _ in range(h)]
    vertical = [[0] * w for _ in range(h)]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = original[r][c]
            if (color not in (0, 3) and original[r-1][c] == 3 and
                    original[r+1][c] == 3 and original[r][c-1] == 3 and
                    original[r][c+1] == 3):
                centers.append((r, c, color))

    for r, c, color in centers:
        for dr, dc, canvas in ((0, -1, horizontal), (0, 1, horizontal),
                               (-1, 0, vertical), (1, 0, vertical)):
            rr, cc = r + dr, c + dc
            distance = 1
            while 0 <= rr < h and 0 <= cc < w:
                cell = original[rr][cc]
                # Pass through this cross's own adjacent arm, but stop at any
                # other cross marker (or colored center) encountered afterward.
                if cell != 0:
                    if distance == 1 and cell == 3:
                        rr += dr
                        cc += dc
                        distance += 1
                        continue
                    break
                if canvas[rr][cc] == 0:
                    canvas[rr][cc] = color
                rr += dr
                cc += dc
                distance += 1

    out = [row[:] for row in original]
    for r in range(h):
        for c in range(w):
            if original[r][c] == 0:
                if horizontal[r][c] != 0:
                    out[r][c] = horizontal[r][c]
                if vertical[r][c] != 0:
                    out[r][c] = vertical[r][c]
