{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = original[r][c]
            if color not in (0, 3) and original[r-1][c] == original[r+1][c] == original[r][c-1] == original[r][c+1] == 3:
                centers.append((r, c, color))

    # Each colored plus sends rays along its row and column. Its own four arms
    # are crossed; any other non-background marker blocks a ray. Vertical rays
    # are layered over horizontal rays at intersections.
    horizontal = [[0] * w for _ in range(h)]
    vertical = [[0] * w for _ in range(h)]
    for r, c, color in centers:
        own_arms = {(r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        for dr, dc, canvas in ((0, -1, horizontal), (0, 1, horizontal),
                               (-1, 0, vertical), (1, 0, vertical)):
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                if original[rr][cc] != 0 and (rr, cc) not in own_arms:
                    break
                if original[rr][cc] == 0:
                    canvas[rr][cc] = color
                rr += dr
                cc += dc
    for r in range(h):
        for c in range(w):
            if original[r][c] == 0:
                if horizontal[r][c]:
                    out[r][c] = horizontal[r][c]
                if vertical[r][c]:
                    out[r][c] = vertical[r][c]
    return out
