    centers = []
    blank_cross_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (original[r-1][c] == original[r+1][c] ==
                    original[r][c-1] == original[r][c+1] == 3):
                color = original[r][c]
                if color == 0:
                    blank_cross_cols.add(c)
                elif color != 3:
                    centers.append((r, c, color))
