    # in all horizontal rays at its column. Existing input marks are preserved;
    # vertical rays overwrite horizontal rays at intersections.
    for r, c, color in centers:
        for j in range(w):
            if j not in blank_cross_cols and original[r][j] == 0:
                out[r][j] = color
    for r, c, color in centers:
        for i in range(h):
            if original[i][c] == 0:
                out[i][c] = color
    return out
