    original = [row[:] for row in grid]
    centers = []
    hollow_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if original[r-1][c] == original[r+1][c] == original[r][c-1] == original[r][c+1] == 3:
                if original[r][c] == 0:
                    hollow_cols.add(c)
                elif original[r][c] != 3:
                    centers.append((r, c, original[r][c]))
    out = [row[:] for row in original]
    # Each colored cross extends its color horizontally and vertically. A hollow
    # cross interrupts the horizontal line at its column. Existing marks remain.
    for r, c, color in centers:
        for j in range(w):
            if j not in hollow_cols and original[r][j] == 0:
                out[r][j] = color
    for r, c, color in centers:
        for i in range(h):
            if original[i][c] == 0:
                out[i][c] = color
    return out
