 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in src]
    centers = []
    gaps = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if src[r-1][c] == src[r+1][c] == src[r][c-1] == src[r][c+1] == 3:
                if src[r][c] == 0:
                    gaps.add(c)
                elif src[r][c] != 3:
                    centers.append((r, c, src[r][c]))
    # Colored pluses extend along their rows and columns. A hollow 3-plus
    # creates a gap at its column in every horizontal stroke.
    for r, c, color in centers:
        for j in range(w):
            if j not in gaps and src[r][j] == 0:
                out[r][j] = color
    # Vertical strokes take precedence where colored lines cross.
    for r, c, color in centers:
        for i in range(h):
            if src[i][c] == 0:
                out[i][c] = color
    return out
