                centers.append((r, c, v))
    horizontal = [[0] * w for _ in range(h)]
    vertical = [[0] * w for _ in range(h)]
    for r, c, color in centers:
        arms = {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
        for dr, dc, layer in ((0,-1,horizontal),(0,1,horizontal),(-1,0,vertical),(1,0,vertical)):
            rr, cc = r+dr, c+dc
            while 0 <= rr < h and 0 <= cc < w:
                if src[rr][cc] != 0 and (rr,cc) not in arms:
